Para crear un comportamiento similar a la consulta en vivo de jQuery, sin la necesidad de simular clicks, se puede usar el evento ` MouseEvent bubbles` y un método recursivo para capturar/clonar el comportamiento de `on` en jQuery:

```javascript
const body = document.body;

function on(element, eventType, handler) {
  if (element.addEventListener) {
    element.addEventListener(eventType, handler);
  } else if (element.attachEvent) { // IE < 9
    element.attachEvent('on' + eventType, handler);
  }
}

function one(element, eventType, handler) {
  on(element, eventType, function(e) {
    handler.call(element, e);
    on(element, eventType, function() {}); // remove the event listener
  });
}

function delegate(element, eventType, selector, handler) {
  const matchedElements = element.querySelectorAll(selector);
  for (let I = 0; I < matchedElements.length; i++) {
    one(matchedElements[i], eventType, handler);
  }

  on(element, eventType, function(e) {
    let targetElement = e.target;
    while (!targetElement.matches(selector) && targetElement !== element) {
      targetElement = targetElement.parentNode;
    }
    if (targetElement === element) {
      return;
    }
    e.stopPropagation(); // prevent event bubbling to parent elements
    handler.call(targetElement, e);
  });
}

// Example usage:
delegate(body, 'click', '.xxx', function(e) {
  // realizar acciones para el elemento con la clase ".xxx" al recibir un click
});
```

